<template><div class="s1-ui"><Alert show-icon>受保护号码、电话、地址留空表示保留；不会将掩码作为原值提交。材料只用于该商户进件，不改变本平台人员身份。</Alert><Form :model="form" :label-width="160" class="ui-form"><DetailSection title="主体与经营授权" :grid="false"><FormItem label="材料使用授权依据" required><Input v-model="form.authorizationBasis" type="textarea" :rows="3" maxlength="500" :disabled="disabled"/></FormItem><div class="ui-form-grid"><FormItem label="商户简称" required><Input v-model="form.shortName" maxlength="64" :disabled="disabled"/></FormItem><FormItem label="获准行业名称" required><Input v-model="form.industryName" maxlength="200" :disabled="disabled"/></FormItem><FormItem label="渠道结算规则编号" required><InputNumber v-model="form.settlementId" :min="1" :max="2147483647" :precision="0" :disabled="disabled"/></FormItem><FormItem label="已批准营业执照" required><Select v-model="form.licenseFileId" :disabled="disabled" clearable><Option v-for="l in licenses" :key="l.id" :value="l.id">{{l.label}}</Option></Select><p class="ui-note">来自本Store已批准资质，不能用其他店文件代替。</p></FormItem></div><AttachmentList v-if="form.licenseFileId" :value="form.licenseFileId" purpose="QUALIFICATION" title="当前选择的营业执照"/></DetailSection><DetailSection title="法定代表人证件" :grid="false"><DocumentForm v-model="form.legalId" :scope="scope+':legal'" prefix="legalId" :protected-values="protectedFields" :disabled="disabled"/></DetailSection><DetailSection title="渠道管理员与代理授权" :grid="false"><div class="ui-form-grid"><FormItem label="联系人身份" required><Select v-model="form.contact.type" :disabled="disabled"><Option value="LEGAL">法定代表人</Option><Option value="AGENT">代理人</Option></Select></FormItem><FormItem label="联系人姓名" required><Input v-model="form.contact.name" maxlength="100" :disabled="disabled"/></FormItem><FormItem label="联系电话" required><Input v-model="form.contact.phone" maxlength="20" :disabled="disabled" :placeholder="protectedFields['contact.phone']?'已有受保护号码，留空保留':''"/><p v-if="protectedFields['contact.phone']" class="ui-meta">已保存：{{protectedFields['contact.phone']}}</p></FormItem></div><DocumentForm v-if="form.contact.type==='AGENT'" :value="form.contact.identity||{}" :scope="scope+':contact'" prefix="contact.identity" :protected-values="protectedFields" :disabled="disabled" @input="form.contact={...form.contact,identity:$event}"/><AttachmentList v-model="form.contact.authorizationFileId" :scope="scope+':authorization'" purpose="CHANNEL" title="代理授权文件" editable :disabled="disabled"/></DetailSection><DetailSection title="结算账户材料" :grid="false"><div class="ui-form-grid"><FormItem label="账户类型" required><Select v-model="form.account.type" :disabled="disabled"><Option value="PUBLIC">对公账户</Option><Option value="PRIVATE">法定代表人个人账户</Option></Select></FormItem><FormItem label="开户名称" required><Input v-model="form.account.name" maxlength="128" :disabled="disabled"/></FormItem><FormItem label="银行账号" required><Input v-model="form.account.number" maxlength="128" :disabled="disabled" :placeholder="protectedFields['account.number']?'已有受保护账号，留空保留':''"/><p v-if="protectedFields['account.number']" class="ui-meta">已保存：{{protectedFields['account.number']}}</p></FormItem><FormItem label="开户银行渠道编码" required><Input v-model="form.account.bankCode" maxlength="10" :disabled="disabled"/></FormItem><FormItem label="支行联行号"><Input v-model="form.account.bankBranchId" maxlength="64" :disabled="disabled"/></FormItem><FormItem label="完整支行名称"><Input v-model="form.account.bankName" maxlength="128" :disabled="disabled"/></FormItem></div><p class="ui-note">银行／支行要求由后端渠道目录校验，不能用前端开关免除。</p></DetailSection><DetailSection title="经营场景" :grid="false"><FormItem label="经营场景名称" required><Input v-model="form.sales.name" maxlength="256" :disabled="disabled"/></FormItem><FormItem label="经营场景链接"><Input v-model="form.sales.url" maxlength="1024" :disabled="disabled"/></FormItem><FormItem label="商户小程序AppID"><Input v-model="form.sales.merchantMiniAppId" maxlength="256" :disabled="disabled"/></FormItem><AttachmentList v-model="form.sales.qrFileId" :scope="scope+':salesQr'" purpose="CHANNEL" title="经营场景二维码" editable images-only :disabled="disabled"/></DetailSection><DetailSection title="受益所有人与补充材料" :grid="false"><Checkbox v-model="form.soleBeneficialOwner" :disabled="disabled">法定代表人是唯一受益所有人</Checkbox><template v-if="!form.soleBeneficialOwner"><p class="ui-note">未勾选替换时保留已有受益人材料，不能将脱敏摘要覆盖为原文。</p><Checkbox v-model="replaceOwners" :disabled="disabled">本次填写或替换受益所有人</Checkbox><div v-if="replaceOwners"><DetailSection v-for="(owner,i) in owners" :key="i" :title="'受益所有人 '+(i+1)" :grid="false"><DocumentForm v-model="owners[i]" :scope="scope+':beneficial:'+i" :prefix="'beneficialOwners.'+i" :disabled="disabled"/><Button :disabled="disabled" @click="owners.splice(i,1)">移除此项</Button></DetailSection><Button :disabled="disabled||owners.length>=4" @click="owners.push({})">新增受益所有人</Button></div></template><AttachmentList v-model="form.specialQualificationFileIds" :scope="scope+':special'" purpose="CHANNEL" title="专项资质附件" editable multiple :maximum="5" :disabled="disabled"/><AttachmentList v-model="form.additionFileIds" :scope="scope+':addition'" purpose="CHANNEL" title="补充附件" editable multiple :maximum="15" :disabled="disabled"/><FormItem label="补充说明"><Input v-model="form.additionDescription" type="textarea" maxlength="512" :disabled="disabled"/></FormItem></DetailSection><FormItem label="材料变更原因" required><Input v-model="reasonText" type="textarea" :rows="3" maxlength="500" :disabled="disabled"/></FormItem></Form><p class="ui-meta">材料规范 {{form.schemaVersion}}</p><p v-if="error||localError" class="ui-error">{{error||localError}}</p><footer class="ui-form-footer"><Button :disabled="disabled" @click="$emit('cancel')">取消</Button><Button type="primary" :disabled="disabled" @click="save">保存材料版本</Button></footer></div></template>
<script>import accessible from './accessibility';import DetailSection from './components/DetailSection';import AttachmentList from './components/AttachmentList';import DocumentForm from './components/DocumentForm';function compact(value){if(Array.isArray(value))return value.map(compact);if(value&&typeof value==='object'){const result={};for(const [k,v] of Object.entries(value))if(v!==''&&v!==undefined)result[k]=compact(v);if(result.longTerm)result.validThrough=null;return result;}return value;}export default {mixins:[accessible],components:{DetailSection,AttachmentList,DocumentForm},props:{value:Object,scope:{type:String,required:true},protectedFields:{type:Object,default:()=>({})},licenses:{type:Array,default:()=>[]},disabled:Boolean,error:String},data(){const old=JSON.parse(JSON.stringify(this.value||{}));delete old.beneficialOwners;return {form:{schemaVersion:'WX_ECOMMERCE_S1_20260509',legalId:{},contact:{},account:{},sales:{},specialQualificationFileIds:[],additionFileIds:[],...old},reasonText:'',replaceOwners:false,owners:[],localError:''};},watch:{form:{deep:true,handler(){this.$emit('dirty');}},reasonText(){this.$emit('dirty');}},methods:{save(){this.localError='';if(!this.reasonText.trim()){this.localError='请填写本次材料变更原因。';return;}const materials=compact(this.form);if(materials.soleBeneficialOwner)materials.beneficialOwners=[];else if(this.replaceOwners)materials.beneficialOwners=this.owners.map(compact);this.$emit('save',{materials,reason:this.reasonText.trim()});}}};</script>
